🐛 Bug
It looks like graphs return multiple outputs as Tuples by default now.
However, the Differentiate function in autodiff.h / autodiff.cpp does not handle this correctly when returning multiple outputs.
It incorrectly adds extra gradOutput nodes for all outputs that are not output[0] separately in the graph.
Here's an example:
Graph: here %7 and %8 are the finput and fgradinput buffers, so they are not part of f_real_outputs
graph(%self : Dynamic
      %weight : Dynamic
      %bias : Dynamic) {
  %0 : int[] = prim::Constant[value=[3, 5]]()
  %1 : int[] = prim::Constant[value=[1, 1]]()
  %2 : int[] = prim::Constant[value=[1, 1]]()
  %6 : Dynamic, %7 : Dynamic, %8 : Dynamic = aten::thnn_conv2d_forward(%self, %weight, %0, %bias, %1, %2)
  %9 : Tuple = prim::TupleConstruct(%6, %7, %8)
  return (%9);
}

You can construct this graph via:
  std::vector<int64_t> input_size = {4, 3, 5, 7}; // B x C x H x W
  std::vector<int64_t> kernel_size = {3, 5};
  std::vector<int64_t> stride = {1, 1};
  std::vector<int64_t> padding = {1, 1};
  constexpr int out_channels = 5;

  auto graph = std::make_shared<Graph>();
  auto ksz_val = graph->insertConstant(IValue(kernel_size));
  auto kst_val = graph->insertConstant(IValue(stride));
  auto pad_val = graph->insertConstant(IValue(padding));

  auto input = graph->addInput("self");
  auto weight = graph->addInput("weight");
  auto bias = graph->addInput("bias");

  Value* conv = graph->insert(aten::thnn_conv2d_forward, {input, weight, ksz_val, bias, kst_val, pad_val});
  auto outputs = conv->node()->outputs();
  for (auto output : outputs) {
    graph->registerOutput(output);
  }
  graph->lint();
Differentiate this graph using:
EliminateDeadCode(graph); // Tracing of some ops depends on the DCE trick
ConstantPropagation(graph);
auto grad_spec = differentiate(graph);
LowerGradOf(*grad_spec.df);
The df graph is:
graph(%0 : Tuple
      %1 : Dynamic
      %2 : Dynamic
      %self : Dynamic
      %weight : Dynamic
      %5 : Dynamic
      %6 : Dynamic) {
  %7 : int[] = prim::Constant[value=[1, 1]]()
  %8 : int[] = prim::Constant[value=[3, 5]]()
  %24 : int = prim::AnyDefined(%0)
  %25 : Dynamic, %26 : Dynamic, %27 : Dynamic = prim::If(%24)
    block0() {
      %28 : Dynamic, %29 : Dynamic, %30 : Dynamic = prim::TupleUnpack(%0)
      -> (%28, %29, %30)
    }
    block1() {
      %31 : Dynamic = prim::Undefined()
      -> (%31, %31, %31)
    }
  %15 : Dynamic = prim::AutogradAdd(%2, %27)
  %16 : Dynamic = prim::AutogradAdd(%1, %26)
  %32 : int = prim::AnyDefined(%25, %16, %15)
  %33 : Dynamic, %34 : Dynamic, %35 : Dynamic = prim::If(%32)
    block0() {
      %36 : bool[] = prim::Constant[value=[1, 1, 1]]()
      %37 : Dynamic, %38 : Dynamic, %39 : Dynamic = aten::thnn_conv2d_backward(%25, %self, %weight, %8, %7, %7, %5, %6, %36)
      -> (%37, %38, %39)
    }
    block1() {
      %40 : Dynamic = prim::Undefined()
      -> (%40, %40, %40)
    }
  return (%33, %34, %35);
}

Now follow along %1, %2, which are gradout_finput and gradout_fgradinput. They shouldn't have been there as inputs at all, because %0 as a Tuple has these as %0[1] and %0[2]. In fact, if you see the graph, the unpacked version %0[1] is AutogradAdded to %1 in the line %16 : Dynamic = prim::AutogradAdd(%1, %26)
Environment
pytorch master
You will need my patches adding autodiff formulas for TupleConstruct and aten::thnn_conv2d_forward here: https://gist.github.com/soumith/f28ab0dd859f8772ff98b1c0f683acbc
